import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"调试接口","link":"/api/SIMD-API/basic_api/debug_interface/debug_interface"},{"text":"异常检测","link":"/api/SIMD-API/basic_api/debug_interface/exception_detection/exception_detection"},{"text":"CheckLocalMemoryIA(ISASI)","link":"/api/SIMD-API/basic_api/debug_interface/exception_detection/CheckLocalMemoryIA_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/debug_interface/exception_detection/CheckLocalMemoryIA_ISASI.md","filePath":"api/SIMD-API/basic_api/debug_interface/exception_detection/CheckLocalMemoryIA_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/debug_interface/exception_detection/CheckLocalMemoryIA_ISASI.md"};function e(t,s,i,d,r,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>CheckLocalMemoryIA(ISASI)<span id="ZH-CN_TOPIC_0000001834740621"></span></h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_common_intf.h&quot;</code>。 check设定范围内的Unified Buffer（UB）读写行为，如果有设定范围的读写行为则会出现EXCEPTION报错，无设定范围的读写行为则不会报错。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CheckLocalMemoryIA</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">CheckLocalMemoryIAParam</span><span class="o">&amp;</span><span class="w"> </span><span class="n">checkParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>checkParams</td><td>输入</td><td>用于配置对UB访问的检查行为，类型为CheckLocalMemoryIAParam。<br>具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_mm.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。<br>参数说明请参考<a href="#table15780447181917">表2</a>。</td></tr></tbody></table><p><strong>表2</strong> CheckLocalMemoryIAParam结构体内参数说明<span id="table15780447181917"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>enableBit</td><td>配置的异常寄存器，取值范围：enableBit∈[0,3]，默认为0。<br>• 0：异常寄存器0。<br>• 1：异常寄存器1。<br>• 2：异常寄存器2。<br>• 3：异常寄存器3。</td></tr><tr><td>startAddr</td><td>Check的起始地址，32B对齐，取值范围：startAddr∈[0, 65535]，默认值为0。比如，可通过LocalTensor.GetPhyAddr()/32来获取startAddr。</td></tr><tr><td>endAddr</td><td>Check的结束地址，32B对齐，取值范围：endAddr∈[0, 65535]。默认值为0。</td></tr><tr><td>isScalarRead</td><td>Check标量读访问。<br>•false：不开启，默认为false。<br>•true：开启。</td></tr><tr><td>isScalarWrite</td><td>Check标量写访问。<br>•false：不开启，默认为false。<br>•true：开启。</td></tr><tr><td>isVectorRead</td><td>Check矢量读访问。<br>•false：不开启，默认为false。<br>•true：开启。</td></tr><tr><td>isVectorWrite</td><td>Check矢量写访问。<br>•false：不开启，默认为false。<br>•true：开启。</td></tr><tr><td>isMteRead</td><td>Check MTE读访问。<br>•false：不开启，默认为false。<br>•true：开启。</td></tr><tr><td>isMteWrite</td><td>Check MTE写访问。<br>•false：不开启，默认为false。<br>•true：开启。</td></tr><tr><td>isEnable</td><td>是否使能enableBit参数配置的异常寄存器。<br>•false：不使能，默认为false。<br>•true：使能。</td></tr><tr><td>reserved</td><td>预留参数。为后续的功能做保留，开发者暂时无需关注，使用默认值即可。</td></tr></tbody></table><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>startAddr/endAddr的单位是32B，check的范围不包含startAddr，包含endAddr，即(startAddr,endAddr]。</li><li>每次调用完该接口需要进行复位（配置isEnable为false进行复位）。</li><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>该示例check矢量写访问是否在设定的(startAddr, endAddr]范围内。当前示例check到矢量写在设定的范围内，结果会报错（ACL_ERROR_RT_VECTOR_CORE_EXCEPTION）。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">TPipe</span><span class="w"> </span><span class="n">pipe</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">TQue</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECIN</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">inQueueSrc0</span><span class="p">,</span><span class="w"> </span><span class="n">inQueueSrc1</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">TQue</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECOUT</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">outQueueDst</span><span class="p">;</span>
<span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">inQueueSrc0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">inQueueSrc1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">outQueueDst</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src0Local</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">inQueueSrc0</span><span class="p">.</span><span class="n">DeQue</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src1Local</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">inQueueSrc1</span><span class="p">.</span><span class="n">DeQue</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">outQueueDst</span><span class="p">.</span><span class="n">AllocTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">CheckLocalMemoryIA</span><span class="p">({</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="p">)(</span><span class="n">dstLocal</span><span class="p">.</span><span class="n">GetPhyAddr</span><span class="p">()</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">32</span><span class="p">),(</span><span class="kt">uint32_t</span><span class="p">)((</span><span class="n">dstLocal</span><span class="p">.</span><span class="n">GetPhyAddr</span><span class="p">()</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">512</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">))</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">32</span><span class="p">),</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span>
<span class="nb">true</span><span class="w"> </span><span class="p">});</span>
</code></pre></div></article></div>`,1)])])}const u=a(c,[["render",e]]);export{A as __pageData,u as default};
